// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intent.classifierimport timber.log.Timberimport com.roshan.persona.brain.intent.Intentimport kotlin.reflect.KClassimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Stage 1: Regex Intent Matcher. * * Pre-compiled regex patterns with capture groups. Fastest classifier path — * handles ~50% of all intents. Returns intent + extracted slots in one pass. * * Each [RegexIntentPattern] declares: *   - the regex pattern (with capture groups for slot extraction) *   - the intent type it produces *   - a factory that converts regex match groups → typed Intent * * @see <a href="docs/spec/module2-spec-review.pdf">§4.1 Stage 1</a> */@Singletonclass RegexIntentMatcher @Inject constructor() {    private val patterns: List<RegexIntentPattern> = listOf(        // ─── Torch ────────────────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:turn\\s+on|enable)\\s+(?:the\\s+)?torch\\b|\\btorch\\s+on\\b"),            intentType = Intent.TorchOn::class,            factory = { _ -> Intent.TorchOn },        ),        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:turn\\s+off|disable)\\s+(?:the\\s+)?torch\\b|\\btorch\\s+off\\b"),            intentType = Intent.TorchOff::class,            factory = { _ -> Intent.TorchOff },        ),        // ─── Volume ───────────────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\bvolume\\s+up(?:\\s+(\\d+))?\\b|\\b(?:louder|increase\\s+volume)(?:\\s+(\\d+))?\\b"),            intentType = Intent.VolumeUp::class,            slotExtractors = mapOf("amount" to listOf(1, 2)),            factory = { slots ->                Intent.VolumeUp(amount = slots["amount"]?.toIntOrNull())            },        ),        RegexIntentPattern(            pattern = Regex("(?i)\\bvolume\\s+down(?:\\s+(\\d+))?\\b|\\b(?:quieter|decrease\\s+volume)(?:\\s+(\\d+))?\\b"),            intentType = Intent.VolumeDown::class,            slotExtractors = mapOf("amount" to listOf(1, 2)),            factory = { slots ->                Intent.VolumeDown(amount = slots["amount"]?.toIntOrNull())            },        ),        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:set\\s+)?volume\\s+(?:to\\s+)?(\\d{1,3})(?:\\s*%)?\\b"),            intentType = Intent.SetVolume::class,            slotExtractors = mapOf("level" to listOf(1)),            factory = { slots ->                Intent.SetVolume(level = slots["level"]?.toIntOrNull() ?: 50)            },        ),        // ─── Brightness ───────────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:set\\s+)?brightness\\s+(?:to\\s+)?(\\d{1,3})(?:\\s*%)?\\b"),            intentType = Intent.SetBrightness::class,            slotExtractors = mapOf("level" to listOf(1)),            factory = { slots ->                Intent.SetBrightness(level = (slots["level"]?.toIntOrNull() ?: 50).coerceIn(0, 100))            },        ),        // ─── Mute / Unmute ────────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:mute|silence)\\b"),            intentType = Intent.Mute::class,            factory = { _ -> Intent.Mute },        ),        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:unmute|restore\\s+sound)\\b"),            intentType = Intent.Unmute::class,            factory = { _ -> Intent.Unmute },        ),        // ─── Phone number extraction (for Call/SMS) ───────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\bcall\\s+(?:\\+?(\\d{10,15})|([a-zA-Z][a-zA-Z\\s]+?))\\b"),            intentType = Intent.Call::class,            slotExtractors = mapOf("phone" to listOf(1), "contact_name" to listOf(2)),            factory = { slots ->                val contact = slots["contact_name"]?.takeIf { it.isNotBlank() }                    ?: slots["phone"]                Intent.Call(contact = contact)            },        ),        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:send\\s+)?sms\\s+(?:to\\s+)?(?:\\+?(\\d{10,15})|([a-zA-Z][a-zA-Z\\s]+?))(?:\\s*:|\\s+saying|\\s+message)?\\s*(.*)?"),            intentType = Intent.SendSms::class,            slotExtractors = mapOf("phone" to listOf(1), "contact_name" to listOf(2), "message" to listOf(3)),            factory = { slots ->                val contact = slots["contact_name"]?.takeIf { it.isNotBlank() }                    ?: slots["phone"]                Intent.SendSms(contact = contact, message = slots["message"]?.takeIf { it.isNotBlank() })            },        ),        // ─── Open app ─────────────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:open|launch|start)\\s+(?:the\\s+)?([a-zA-Z][a-zA-Z0-9\\s]*?)\\s*(?:app|application)?$"),            intentType = Intent.OpenApp::class,            slotExtractors = mapOf("app_name" to listOf(1)),            factory = { slots ->                Intent.OpenApp(appName = slots["app_name"]?.trim(), packageName = null)            },        ),        // ─── Web search ───────────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:search(?:\\s+for)?|google|look\\s+up)\\s+(.+?)\\b"),            intentType = Intent.SearchWeb::class,            slotExtractors = mapOf("query" to listOf(1)),            factory = { slots ->                Intent.SearchWeb(query = slots["query"])            },        ),        // ─── Alarm ────────────────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:set\\s+)?alarm\\s+(?:for\\s+)?(\\d{1,2}(?::\\d{2})?\\s*(?:am|pm)?)(?:\\s+(?:called|labeled|with\\s+label)\\s+(.+))?\\b"),            intentType = Intent.SetAlarm::class,            slotExtractors = mapOf("time" to listOf(1), "label" to listOf(2)),            factory = { slots ->                Intent.SetAlarm(time = slots["time"], label = slots["label"])            },        ),        // ─── Timer ────────────────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:set\\s+)?timer\\s+(?:for\\s+)?(\\d+)\\s*(minutes?|hours?|seconds?)\\b"),            intentType = Intent.SetTimer::class,            slotExtractors = mapOf("duration" to listOf(1), "unit" to listOf(2)),            factory = { slots ->                Intent.SetTimer(duration = "${slots["duration"]} ${slots["unit"]}")            },        ),        // ─── List automations ─────────────────────────────────────────────        RegexIntentPattern(            pattern = Regex("(?i)\\b(?:list|show|what\\s+are)\\s+(?:my\\s+)?automations\\b"),            intentType = Intent.ListAutomations::class,            factory = { _ -> Intent.ListAutomations },        ),    )    /**     * Try to match [input] against all regex patterns.     *     * @return [RegexMatch] if matched, null otherwise.     */    fun match(input: String): RegexMatch? {        for (pattern in patterns) {            val matchResult = pattern.pattern.find(input)            if (matchResult != null) {                val slots = mutableMapOf<String, String>()                for ((slotName, groupIdxList) in pattern.slotExtractors) {                    for (groupIdx in groupIdxList) {                        val value: String? = try {                            matchResult.groups[groupIdx]?.value                        } catch (e: Throwable) {                            Timber.tag("NOUS.L0").w("Regex match failed", e)                            null                        }                        if (!value.isNullOrBlank()) {                            slots[slotName] = value.trim()                            break                        }                    }                }                val intent = pattern.factory(slots)                return RegexMatch(                    intent = intent,                    slots = slots,                    intentType = pattern.intentType,                )            }        }        return null    }    /** Pre-compiled regex pattern + intent factory. */    private data class RegexIntentPattern(        val pattern: Regex,        val intentType: KClass<out Intent>,        val slotExtractors: Map<String, List<Int>> = emptyMap(),        val factory: (Map<String, String>) -> Intent,    )    /** Result of regex match. */    data class RegexMatch(        val intent: Intent,        val slots: Map<String, String>,        val intentType: KClass<out Intent>,    )}